INSERT INTO `messages` VALUES (1,1,1,'三重旅行、伊勢神宮は外せないよね！',NULL,'2026-06-18 16:00:00','visible',NULL),(2,1,2,'鳥羽水族館にも行きたいです。',NULL,'2026-06-18 16:02:00','visible',NULL),(3,1,3,'宿は温泉付きで探してみます。',NULL,'2026-06-18 16:05:00','visible',NULL),(4,1,1,'予算は1人5万円くらいを目安にしよう。',NULL,'2026-06-18 16:10:00','visible',NULL),(5,2,2,'3名でコテージの宿泊を考えています。8月20日〜22日の空室はありますか？',NULL,'2026-06-20 12:10:00','visible',NULL),(6,2,8,'お問い合わせありがとうございます！8月20日〜22日（2泊3日）、3名様でのご利用ですね。その日程は空室がございます。',NULL,'2026-06-20 13:00:00','visible',NULL),(7,2,8,'コテージAは最大4名様までご利用いただけます。BBQスペースも完備しており、グループ旅行に最適です。ご興味はいかがでしょうか？',NULL,'2026-06-20 13:02:00','visible',NULL),(8,2,2,'BBQ付きはいいですね！料金を教えていただけますか？',NULL,'2026-06-20 13:30:00','visible',NULL),(9,2,8,'コテージA（最大4名）の2泊分の料金は36,000円（税込）です。3名様でご利用の場合、お1人あたり約12,000円になります。',NULL,'2026-06-20 14:00:00','visible',NULL),(10,2,8,'チェックインは15:00〜、チェックアウトは11:00となっております。駐車場は無料でご利用いただけます。',NULL,'2026-06-20 14:02:00','visible',NULL),(11,2,2,'ありがとうございます！グループで相談してまた連絡します。',NULL,'2026-06-20 14:30:00','visible',NULL),(12,2,8,'ごゆっくりご検討ください。ご予約はお早めにどうぞ。ご不明な点があればいつでもお気軽にご連絡ください！',NULL,'2026-06-20 14:35:00','visible',NULL),(13,3,2,'北海道はまず札幌から回るのはどう？',NULL,'2026-06-19 18:00:00','visible',NULL),(14,3,1,'賛成！午後は小樽運河にも行きたい。',NULL,'2026-06-19 18:05:00','visible',NULL),(15,2,8,'お問い合わせありがとうございます。3名様の空室をご用意できます。ご希望の日程を教えてください。',NULL,'2026-06-20 13:00:00','visible',NULL),(16,2,1,'8月20日から22日で、3名でお願いできますか？',NULL,'2026-06-20 14:00:00','visible',NULL),(17,2,8,'はい、その日程でご予約可能です。到着予定時刻をお知らせください。',NULL,'2026-06-20 14:30:00','visible',NULL),(18,1,5,'こんちゃ',NULL,'2026-07-13 05:41:21','visible',NULL),(19,1,6,'おひさしぶりどす',NULL,'2026-07-13 06:22:22','visible',NULL),(20,1,3,'ちゃす',NULL,'2026-07-13 06:22:27','visible',NULL),(21,1,3,NULL,'/TABI/uploads/chat/20260713_152249_63a8cb46b0e6.jpg','2026-07-13 06:22:49','visible',NULL),(22,1,6,'わ',NULL,'2026-07-23 05:04:36','visible',NULL),(23,1,2,'は',NULL,'2026-09-02 06:32:28','visible',NULL);
